export const CORRECTIONS = {"cliapprum--gi-surgery-sawita--diagnostic-ping-sound-map":[{"severity":"narrows","lectureSays":"\"Ping ที่ right flank rib 9-13 upper third = RDA / RAV\" โดยใช้ตำแหน่ง ping เป็นตัวชี้โรคแบบหนึ่งต่อหนึ่ง","evidenceSays":"ในโคโตเต็มวัย 366 ตัวที่มี right-side ping แหล่งกำเนิดเสียงคือ abomasum 137 ตัว, ลำไส้ส่วนต่าง ๆ 157 ตัว, peritoneal gas 2 ตัว และระบุไม่ได้ 70 ตัว การระบุ cecum และ/หรือ ascending colon ทางคลินิกมี sensitivity และ predictive value 87% ทั้งคู่ และ final diagnosis ที่พบมากที่สุดในโคที่มี ping ด้านขวากลับเป็น LDA (The identification of structures and conditions responsible for right side tympanitic resonance (ping) in adult cattle, PMID 7083866)","examAdvice":"ถ้าโจทย์ถามตำแหน่ง ping ตรง ๆ ให้ตอบ RDA / RAV ตามเลกเชอร์ แต่ถ้าเป็นเคสให้วินิจฉัย อย่าตัดสินจาก ping อย่างเดียว ต้องดู rectal และอาการร่วมด้วย","sourceRef":"PMID 7083866"}],"cliapprum--gi-surgery-sawita--intussusception":[{"severity":"contradicts","lectureSays":"\"Most common: jejunojejunal, ileocolic\" คือระบุว่า ileocolic เป็นชนิดที่พบบ่อยลำดับต้น","evidenceSays":"จาก 336 รายในโค การจำแนกตำแหน่งคือ small intestinal 281 ราย, colocolic 36 ราย, cecocolic 12 ราย และ ileocolic เพียง 7 ราย ทำให้ ileocolic เป็นชนิดที่พบน้อยที่สุด ส่วนลูกโคอายุน้อยกว่า 2 เดือนเสี่ยงต่อ small intestinal intussusception มากกว่าโคที่โตกว่า (Intussusception in cattle: 336 cases (1964-1993), PMID 9040842)","examAdvice":"ถ้าอาจารย์ออกข้อสอบเองและเฉลยตามเลกเชอร์ ให้ตอบ jejunojejunal และ ileocolic ตามที่สอน แต่จำไว้ว่าข้อมูลจริงชนิดที่รองจาก small intestinal คือ colocolic ไม่ใช่ ileocolic","sourceRef":"PMID 9040842"}],"cliapprum--gi-surgery-sawita--lda-left-displaced-abomasum":[{"severity":"narrows","lectureSays":"\"first 30 days post-partum peak, 50-90% concurrent ketosis\" โดยให้สัดส่วน ketosis ร่วมเป็นตัวเลขชัดเจน","evidenceSays":"การศึกษาภาคสนามในโคนม 1,044 ตัว 20 ฟาร์ม พบ incidence risk ของ LDA 5.1% และ median time of diagnosis ที่ 11 วันหลังคลอด โคที่มี serum BHBA ตั้งแต่ 1,200 µmol/L ในช่วง 1-7 วันหลังคลอด มี odds ของการเกิด LDA สูงกว่า 8 เท่า งานนี้ไม่ได้รายงานสัดส่วน concurrent ketosis แบบ 50-90% (Metabolic predictors of displaced abomasum in dairy cattle, PMID 15591379, doi 10.3168/jds.S0022-0302(05)72674-6)","examAdvice":"ตอบ 50-90% ตามเลกเชอร์ถ้าถูกถามตรง ๆ และจำ median 11 วัน กับ BHBA 1,200 µmol/L ไว้ใช้ตอบข้อเขียนหรือเคสเพราะเป็นตัวเลขที่อ้างอิงได้","sourceRef":"PMID 15591379 (doi 10.3168/jds.S0022-0302(05)72674-6)"}],"cliapprum--gi-surgery-sawita--rda-rav-right-displaced-abomasum-volvulus-surgical-emergency":[{"severity":"contradicts","lectureSays":"\"Lactate >4 mM = poor prognosis\" และ Past Exam Mapping ก็เฉลยว่า Q Lactate cutoff prognosis ตอบ >4 mM","evidenceSays":"ในโค Holstein ที่เป็น RDA หรือ abomasal volvulus การวัด plasma L-lactate ข้างฟาร์มก่อนผ่าตัดทำนาย negative outcome ได้ดี (AUC 0.92) จุดตัดที่มีความหมายทางคลินิกคือ 2 และ 6 mmol/L โดยค่า ≤2 mmol/L บ่งชี้ผลลัพธ์ดี ส่วน ≥6 mmol/L มี specificity 97.5% และ positive predictive value 75% ต่อ negative outcome (Preoperative cow-side lactatemia measurement predicts negative outcome in Holstein dairy cattle with right abomasal disorders, PMID 24183688, doi 10.3168/jds.2013-6898)","examAdvice":"ในห้องสอบให้ตอบ >4 mM ตามที่อาจารย์สอนและตามที่ Past Exam Mapping เฉลยไว้ แล้วจำจุดตัดจริง 2 กับ 6 mmol/L ไว้ใช้ตอนทำงานจริง","sourceRef":"PMID 24183688 (doi 10.3168/jds.2013-6898)"}],"cliapprum--gi-surgery-sawita--rumenotomy-overlap-with-vet-prac-rum-aj-ea":[{"severity":"narrows","lectureSays":"\"Indications: TRP (FB removal), grain engorgement (lactic acidosis evacuation), rumen impaction, plant toxin removal\" โดยวาง grain engorgement เป็นข้อบ่งชี้ลำดับต้น","evidenceSays":"ชุดผู้ป่วยจริง 53 ตัวที่ทำ rumenotomy ข้อบ่งชี้เรียงตามความถี่คือ traumatic reticuloperitonitis 31 ตัว, bloat 9 ตัว, foreign body 6 ตัว, choke 5 ตัว และอื่น ๆ 2 ตัว ส่วน grain overload ปรากฏเพียง 1 รายและอยู่ในกลุ่ม rumenostomy ไม่ใช่ rumenotomy (Indications for and factors relating to outcome after rumenotomy or rumenostomy in cattle: 95 cases (1999-2011), PMID 26331425, doi 10.2460/javma.247.6.659)","examAdvice":"ตอบ TRP เป็นข้อบ่งชี้อันดับหนึ่งเสมอ และยังตอบ grain engorgement ว่าเป็นข้อบ่งชี้ได้ตามเลกเชอร์ เพียงอย่าตอบว่าเป็นสาเหตุที่พบบ่อยที่สุด","sourceRef":"PMID 26331425 (doi 10.2460/javma.247.6.659)"}],"cliapprum--gi-vdtt--rumen-fluid-analysis-cowside":[{"severity":"narrows","lectureSays":"\"No protozoa = severe acidosis or post-antibiotic\" คือผูกการไม่พบ protozoa เข้ากับ acidosis ระดับรุนแรงเท่านั้น","evidenceSays":"การลดลงของประชากร ciliated protozoa เป็นลักษณะร่วมของ ruminal acidosis ทั้งแบบ acute และ subacute และผู้เขียนใช้ถ้อยคำว่าอาจใช้เป็น microbial indicator ที่ดีของ acidotic rumen ไม่ได้ยืนยันว่าการไม่พบ protozoa เท่ากับ severe acidosis เสมอไป (Ruminal acidosis in beef cattle: the current microbiological and nutritional outlook, PMID 17517750, doi 10.3168/jds.2006-478)","examAdvice":"ข้อสอบเลือกตอบให้ตอบตามเลกเชอร์ว่าไม่พบ protozoa บ่งชี้ acidosis หรือหลังได้ยาปฏิชีวนะ แต่ถ้าเป็นข้อเขียน ให้เขียนว่าเป็น indicator ของ acidotic rumen โดยไม่ระบุระดับความรุนแรง","sourceRef":"PMID 17517750 (doi 10.3168/jds.2006-478)"}],"cliapprum--hoof-health-fleet--block-application":[{"severity":"narrows","lectureSays":"\"Duration: 3-6 weeks usually\" และ \"trimming flush to ground every 2-4 wk\" เขียนเป็นค่าตายตัว","evidenceSays":"การคงอยู่ของ block ต่างกันตามวัสดุอย่างมาก เทียบกับ plastic shoe โคที่ใส่ wooden block มีโอกาสทำ block หลุดสูงกว่า 4.8 เท่า (95% CI 1.8-12.4) และ foam block สูงกว่า 9.5 เท่า (95% CI 3.6-24.4) ผู้วิจัยประเมิน block ซ้ำที่วันที่ 14 และ 28 และสรุปว่ายังต้องการข้อมูลเพิ่มเพื่อกำหนดระยะเวลาที่เหมาะสม บริบทเป็นโคแทะเล็มในนิวซีแลนด์ที่เดินเฉลี่ยเพียง 0.32 km ต่อวัน (Persistence of orthopaedic hoof blocks for the treatment of lame cattle kept permanently at pasture, PMID 37222341, doi 10.1080/00480169.2023.2216658)","examAdvice":"ตอบ 3-6 สัปดาห์ตามเลกเชอร์ แต่ถ้าเป็นข้อเขียนหรือเคส ให้เสริมว่าต้องนัดตรวจซ้ำเพราะระยะเวลาจริงขึ้นกับวัสดุที่ใช้","sourceRef":"PMID 37222341 (doi 10.1080/00480169.2023.2216658)"}],"cliapprum--metabolism-nutrition--body-condition-score-bcs-1-5-scale":[{"severity":"narrows","lectureSays":"ตาราง BCS ตั้งเป้าวันคลอดไว้ที่ 3.25-3.50","evidenceSays":"ความสัมพันธ์ระหว่าง BCS กับผลผลิตและสุขภาพเป็นแบบ non-linear โดย optimum calving BCS อยู่ที่ 3.0 ถึง 3.25 (สเกล 5 ระดับ) ส่วน calving BCS ตั้งแต่ 3.5 ขึ้นไปสัมพันธ์กับ DMI และผลผลิตน้ำนมช่วงต้นระยะให้นมที่ลดลง และความเสี่ยง metabolic disorders ที่เพิ่มขึ้น (Invited review: Body condition score and its association with dairy cow productivity, health, and welfare, PMID 19923585, doi 10.3168/jds.2009-2431)","examAdvice":"ตอบ 3.25-3.50 ตามเลกเชอร์ในข้อสอบ แต่ในทางปฏิบัติให้เล็งขอบล่างของช่วงคือ 3.25 เพราะ 3.5 คือระดับที่เริ่มมีผลเสีย","sourceRef":"PMID 19923585 (doi 10.3168/jds.2009-2431)"}],"cliapprum--metabolism-nutrition--clinical-dashboard-5-sections":[{"severity":"narrows","lectureSays":"\"Penn State 4-layer, ชั้น 1 (>19mm) 2-8%\" ให้เป็นเป้าหมายเดียว ไม่แยกบริบทโครีดนมกับโคช่วงก่อนคลอด","evidenceSays":"ข้อมูลจาก 72 ฟาร์มพบว่าขนาดอนุภาค TMR ที่วัดด้วย Penn State Particle Separator เป็นตัวแปรระดับคอกที่สัมพันธ์กับ NEFA, BHB, haptoglobin, อุบัติการณ์โรค, milk yield และ pregnancy risk หลังคลอด และสนับสนุนการเพิ่มสัดส่วนอนุภาคบนตะแกรง 19 mm ในสูตรอาหารช่วงก่อนคลอด (Transition cow nutrition and management strategies of dairy herds in the northeastern United States Part III, PMID 36543646, doi 10.3168/jds.2022-21876) นอกจากนี้ Caccamo et al. 2014 พบ protein yield สูงกว่าในกลุ่มที่มีอนุภาคบนตะแกรงบน 10.4-17.4% และสรุปว่า optimum อาจต่างจากค่าที่แนะนำตามภูมิภาค (PMID 24485675, doi 10.3168/jds.2012-6490)","examAdvice":"ข้อสอบถาม Penn State ชั้น 1 ให้ตอบ 2-8% ตามเลกเชอร์ แต่ถ้าโจทย์ระบุว่าเป็นโคช่วงก่อนคลอดหรือ close-up ให้ระวังว่าเป้าหมายไม่ใช่ตัวเลขเดียวกัน","sourceRef":"PMID 36543646 (doi 10.3168/jds.2022-21876); เสริม Caccamo et al. 2014 PMID 24485675"}],"cliapprum--metabolism-nutrition--milk-fat-depression-mfd":[{"severity":"contradicts","lectureSays":"\"trans-10 C18:1 fatty acid form ยับยั้ง milk fat synthesis โดยตรง\"","evidenceSays":"trans-10,cis-12 CLA คือ isomer ที่รับผิดชอบต่อการยับยั้งการสังเคราะห์ไขมันนม การ infuse เข้า abomasum 10 กรัมต่อวันลด milk fat percentage และ milk fat yield ลง 42% และ 44% ตามลำดับ ขณะที่ cis-9,trans-11 CLA ไม่มีผลต่อไขมันนม ส่วน trans-10 C18:1 สูงขึ้นควบคู่กันและใช้เป็น marker ของ biohydrogenation ที่เปลี่ยนทาง แต่งานนี้ไม่ได้แสดงว่ามันคือตัวยับยั้งโดยตรง (Identification of the conjugated linoleic acid isomer that inhibits milk fat synthesis, PMID 10644637, doi 10.1152/ajpregu.2000.278.1.R179)","examAdvice":"ถ้าอาจารย์ออกข้อสอบเองและตัวเลือกมีแต่ trans-10 C18:1 ให้ตอบตามเลกเชอร์ แต่ถ้ามีตัวเลือก trans-10,cis-12 CLA ให้เลือกตัวนั้นเพราะเป็นคำตอบที่ถูกตามหลักฐาน","sourceRef":"PMID 10644637 (doi 10.1152/ajpregu.2000.278.1.R179)"}],"cliapprum--metabolism-nutrition--transition-period-3-weeks-pre-post-calving":[{"severity":"contradicts","lectureSays":"ตาราง marker ระบุ NEFA \">0.4 pre-partum, >0.7 post-partum\"","evidenceSays":"ระดับเตือนระดับฝูงคือมีโคตั้งแต่ 15% ของที่สุ่มตรวจมี postpartum NEFA ตั้งแต่ 0.70 mEq/L ซึ่งสัมพันธ์กับอุบัติการณ์ DA และ clinical ketosis เพิ่มขึ้น 1.7%, pregnancy rate ลดลง 0.9% และ ME305 ที่ลดลง แต่เกณฑ์เตือนระดับฝูงช่วงก่อนคลอดอยู่ที่ 0.27-0.30 mEq/L (PMID 20655428, doi 10.3168/jds.2010-3074) และงานคู่ระดับตัวสัตว์ให้เกณฑ์วิกฤตก่อนคลอดที่ 0.29 mEq/L หลังคลอดที่ 0.57 mEq/L (Ospina et al. 2010, PMID 20105526, doi 10.3168/jds.2009-2277)","examAdvice":"ข้อสอบของอาจารย์ให้ตอบ 0.4 ก่อนคลอด และ 0.7 หลังคลอดตามเลกเชอร์ แต่ให้จำไว้ว่าเกณฑ์ก่อนคลอดที่ใช้อ้างอิงจริงคือราว 0.29-0.30 mEq/L","sourceRef":"PMID 20655428 (doi 10.3168/jds.2010-3074); เสริม Ospina et al. 2010 PMID 20105526 (doi 10.3168/jds.2009-2277)"}],"cliapprum--ruminant-anesthesia--local-regional-block-selection":[{"severity":"narrows","lectureSays":"\"Caudal epidural sacrococcygeal (S5-Co1), Lidocaine 1 ml/100 kg, max 6 ml\" เป็นกฎปริมาตรค่าเดียว","evidenceSays":"Caudal epidural ในโคใช้ตำแหน่ง sacrococcygeal (S5-Co1) หรือ first intercoccygeal (Co1-Co2) เป็นหลัก โดยขนาด lidocaine ที่มีรายงานใช้บ่อยอยู่ที่ 0.22-0.5 mg/kg สำหรับผ่าตัดบริเวณหาง ทวารหนัก vulva perineum เต้านมส่วนท้าย scrotum และขาหลังส่วนบน กฎ 1 ml ต่อ 100 kg ของ lidocaine 2% คิดเป็นราว 0.2 mg/kg ซึ่งอยู่ที่หรือต่ำกว่าขอบล่างของช่วงนี้เล็กน้อย (Epidural analgesia in cattle, buffalo, and camels, PMID 28096620, doi 10.14202/vetworld.2016.1450-1455)","examAdvice":"ตอบ 1 ml ต่อ 100 kg และไม่เกิน 6 ml ตามเลกเชอร์ เพราะเป็นกฎที่คุมไม่ให้โคล้มขณะยืนผ่าตัด และจำไว้ว่าเป็นขนาดค่อนไปทางต่ำของช่วงที่มีรายงาน","sourceRef":"PMID 28096620 (doi 10.14202/vetworld.2016.1450-1455)"}],"cliapprum--ruminant-anesthesia--pre-medication-sedation":[{"severity":"narrows","lectureSays":"\"Xylazine 0.05-0.1 mg/kg IM/IV, reverse: yohimbine 0.125 mg/kg IV\" โดยไม่ระบุว่ากลับฤทธิ์ด้านใด","evidenceSays":"Yohimbine 0.25 mg/kg IV ที่ให้ 3 นาทีหลัง xylazine 0.05 mg/kg IV ในลูกโคหย่านม ลดระยะเวลา rumen amotility จาก 38.3 เหลือ 14.0 นาที และลดระยะเวลาของ xylazine-induced bradycardia แต่ไม่ได้ทำให้ระยะเวลา sedation สั้นลง (Influence of yohimbine on xylazine-induced depression of central nervous, gastrointestinal and cardiovascular function in cattle, PMID 6478835 ซึ่งเป็นตัวระบุที่ค้นได้ เพราะบทความปี 1984 นี้ไม่มี DOI)","examAdvice":"ข้อสอบถามว่ากลับฤทธิ์ xylazine ด้วยอะไร ให้ตอบ yohimbine ที่ 0.125 mg/kg IV ตามเลกเชอร์ แต่ถ้าเป็นข้อเขียน ให้ระบุด้วยว่ากลับฤทธิ์ทาง rumen และหัวใจได้ชัดกว่าฤทธิ์ sedation","sourceRef":"PMID 6478835"}]};
